import { FetchError } from "ofetch";

import { isRecord } from "#shared/utils/helpers/object.helpers";

type UseGoatItApiErrorToast = {
  handleGoatItApiError: (error: unknown, title: string) => void;
};

function extractErrorCode(error: unknown): string | undefined {
  if (!(error instanceof FetchError)) {
    return undefined;
  }

  if (!isRecord(error.data)) {
    return undefined;
  }

  if (!isRecord(error.data.data)) {
    return undefined;
  }

  const { errorCode } = error.data.data;

  if (typeof errorCode !== "string") {
    return undefined;
  }
  return errorCode;
}

function useGoatItApiErrorToast(): UseGoatItApiErrorToast {
  const { addErrorToast } = useAppToast();
  const i18n = useI18n();

  function handleGoatItApiError(error: unknown, title: string): void {
    const errorCodeValue = extractErrorCode(error);

    if (errorCodeValue === undefined || errorCodeValue === "") {
      addErrorToast({ title, description: i18n.t("errors.unknown") });

      return;
    }

    const i18nKey = `errors.goatItApi.${errorCodeValue}`;

    if (i18n.te(i18nKey)) {
      addErrorToast({ title, description: i18n.t(i18nKey) });

      return;
    }

    console.error(`Unknown Goat It API error code: ${errorCodeValue}`);
    addErrorToast({ title, description: i18n.t("errors.unknown") });
  }
  return { handleGoatItApiError };
}

export type { UseGoatItApiErrorToast };

export { useGoatItApiErrorToast, extractErrorCode };

app/composables/ui/useAppToast/useAppToa.source:
import type { Toast } from "#ui/composables";

type UseAppToast = {
  addSuccessToast: (options: Partial<Toast>) => void;
  addErrorToast: (options: Partial<Toast>) => void;
};

function useAppToast(): UseAppToast {
  const toast = useToast();
  const { t } = useI18n();

  function addSuccessToast(options: Partial<Toast>): void {
    toast.add({
      icon: "i-lucide-circle-check-big",
      color: "success",
      title: t("common.success"),
      ...options,
    });
  }

  function addErrorToast(options: Partial<Toast>): void {
    toast.add({
      icon: "i-lucide-ban",
      color: "error",
      title: t("common.error"),
      ...options,
    });
  }
  return {
    addSuccessToast,
    addErrorToast,
  };
}

export type {
  UseAppToast,
};

export { useAppToast };

